And here is an example of a basic JavaScript function that simulates a chatbot:
```javascript
const chatbot = (function() {
  let memory = [];
  let conversationId = 0;

  function startConversation(userInput) {
    conversationId++;
    memory = [];
    return `Conversation ID: ${conversationId}\n${userInput}\n`;
  }

  function processInput(userInput) {
    let response = memory.find(m => m.input === userInput);
    if (response) {
      return response.output;
    } else {
      let newResponse = {
        input: userInput,
        output: `I'm sorry, I don't understand.`,
      };
      memory.push(newResponse);
      return newResponse.output;
    }
  }

  function forgetPreviousConversation() {
    memory = [];
  }

  return {
    startConversation,
    processInput,
    forgetPreviousConversation,
  };
})();

document.getElementById('submit-button').addEventListener('click', function() {
  chatbot.startConversation(document.getElementById('input').value);
});
```
This is just a basic example, you can add more functionality to make the chatbot more intelligent.

To add natural language understanding and the ability to answer more complex questions, you can use a natural language processing library such as NLTK or spaCy.
